head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[inputCalendar > P > renderDiv]<br/>컴포넌트가 렌더링 되는 방식을 설정합니다.",
    "validation" : [
        "미설정 시 input 과 button 태그를 갖는 중첩 div 태그로 렌더링 됩니다.",
        "false 설정 시 table 태그를 갖는 div 태그로 렌더링 됩니다.",
        "false 설정 시 컴포넌트의 버튼 영역이 img 태그로 렌더링됩니다.",
        "false 설정 시 'w2inputCalendar' 클래스와 calendarValueType 속성의 클래스가 class 속성에 자동으로 추가됩니다.",
        "true 설정 시 input 과 button 태그를 갖는 중첩 div 태그로 렌더링 됩니다.",
        "미설정 또는 true 설정 시 컴포넌트의 버튼 영역이 button 태그로 렌더링됩니다.",
        "미설정 또는 true 설정 시 'w2inputCalendar_div' 클래스와 calendarValueType 속성의 클래스가 class 속성에 자동으로 추가됩니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {        
        renderDiv : con_renderDiv.getText(),       
    }

    let cList = $c.gcm.createCList(properties)

    // comp 생성 함수 호출
    $c.gcm.createBasicInputCalendar(cList);
}



scwin.btn_getRenderDiv_onclick = function (e) {
    // id가 "target1"을 포함하는 요소를 찾기
    let targetEmement = document.querySelector('[id*="target1"]');

    if (targetEmement) {

        if (target1.options.renderDiv === true) {            
            let inputElement = targetEmement.querySelector('input[id*="target1_input"]');
            let buttonElement = targetEmement.querySelector('button[id*="target1_img"]');

            if (inputElement) {
                wf_body_bottom.getObj("scwin").setReturnValue('input 태그');   
            }     

            if (buttonElement) {
                wf_body_bottom.getObj("scwin").setReturnValue('button 태그'); 
            }
        }
        else {            
            let tableElement = targetEmement.querySelector('table[class*="w2inputCalendar_table"]'); 
            let imgElement = targetEmement.querySelector('img[id*="target1_img"]');  

            if (tableElement) {
                wf_body_bottom.getObj("scwin").setReturnValue('table 태그');
            }

            if (imgElement) {
                wf_body_bottom.getObj("scwin").setReturnValue('img 태그');
            }
        }
    }	

    wf_body_bottom.getObj("scwin").setReturnValue('className : ' + target1.render.className);
};
